-- AESYN 0.72.1: guarda no banco as chaves que assinam convites, links de senha e de e-mail.
-- Antes elas ficavam dentro do container e sumiam a cada deploy, invalidando os convites ("Invalid token.").
-- So cria uma tabela nova e vazia (nao altera nem apaga nada). Pode rodar mais de uma vez.
BEGIN;

CREATE TABLE IF NOT EXISTS "DataProtectionKeys" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FriendlyName" text NULL,
    "Xml" text NULL,
    CONSTRAINT "PK_DataProtectionKeys" PRIMARY KEY ("Id")
);

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20261029220000_V0721ChavesDataProtection', '10.0.10')
ON CONFLICT ("MigrationId") DO NOTHING;

COMMIT;
